const fs = createFsFromVolume(new Volume()) as unknown as typeof import("node:fs");
let managerId = 0;

class MemoryBgProcessStore {
	private readonly records = new Map<string, PersistedBgProcess>();

	constructor(private readonly root: string) {}
	filesDir(sessionId: string): string { return path.join(this.root, "bg-processes", sessionId); }
	put(record: PersistedBgProcess): void { this.records.set(`${record.sessionId}\0${record.id}`, record); }
	get(sessionId: string, id: string): PersistedBgProcess | undefined { return this.records.get(`${sessionId}\0${id}`); }
	getForSession(sessionId: string): PersistedBgProcess[] {
		return [...this.records.values()].filter((record) => record.sessionId === sessionId);
	}
	update(sessionId: string, id: string, updates: Partial<UpdatableBgFields>): void {
		const record = this.get(sessionId, id);
		if (record) Object.assign(record, updates);
	}
	remove(sessionId: string, id: string): void { this.records.delete(`${sessionId}\0${id}`); }
	removeForSession(sessionId: string): void {
		for (const record of this.getForSession(sessionId)) this.remove(sessionId, record.id);
	}
	flush(): void {}
}

interface FakeChild extends EventEmitter {
	pid: number;
	stdout: EventEmitter & { destroy(): void };
	stderr: EventEmitter & { destroy(): void };
	kill(_sig?: string): boolean;
	unref(): void;
}

function makeFakeChild(): FakeChild {
	const child = new EventEmitter() as FakeChild;
	child.pid = Math.floor(Math.random() * 1_000_000) + 1000;
	const mkStream = () => Object.assign(new EventEmitter(), { destroy() { /* noop */ } });
	child.stdout = mkStream();
	child.stderr = mkStream();
	child.kill = () => true;
	child.unref = () => { /* noop */ };
	return child;
}

function makeManager(env?: Partial<BgEnv>, onSpawn?: (paths: BgPaths) => void) {
	const stateDir = path.join(os.tmpdir(), `bobbit-bgmgr-${++managerId}`);
	fs.mkdirSync(stateDir, { recursive: true });
	const store = new MemoryBgProcessStore(stateDir);
	let last: FakeChild | null = null;
	let spawnCalls = 0;
	const spawn: SpawnFn = (_command, _cwd, _containerId, paths) => {
		spawnCalls++;
		onSpawn?.(paths);
		last = makeFakeChild();
		return last as unknown as ChildProcess;
	};
	const tailerStops: string[] = [];
	const tailerSpecs: any[] = [];
	const tailerFactory: TailerFactory = (spec) => {
		tailerSpecs.push(spec);
		const mk = (stream: string): Tailer => ({ start() {}, stop() { tailerStops.push(stream); } });
		return { out: mk("stdout"), err: mk("stderr") };
	};
	const killCalls: Array<[number, string]> = [];
	const fullEnv: BgEnv = {
		isHostPidAlive: env?.isHostPidAlive ?? (() => false),
		killHostTree: env?.killHostTree ?? ((pid, sig) => killCalls.push([pid, sig])),
		dockerCli: env?.dockerCli ?? (() => ({ code: 0, stdout: "" })),
	};
	const clock = createManualClock();
	const sent: any[] = [];
	const client = { readyState: 1, send: (data: string) => sent.push(JSON.parse(data)) };
	const mgr = new BgProcessManager(
		() => new Set([client]) as any,
		spawn,
		() => store as unknown as BgProcessStore,
		tailerFactory,
		fullEnv,
		clock,
		fs,
	);
	return {
		mgr, stateDir, store, clock, sent, tailerStops, tailerSpecs,
		spawnCalls: () => spawnCalls,
		last: () => { if (!last) throw new Error("spawn not called"); return last; },
		killCalls,
		/** Drive a clean exit: write the status file then emit the child `exit` hint. */
		driveExit(session: string, id: string, code = 0) {
			const rec = store.get(session, id)!;
			fs.writeFileSync(rec.statusSnapshot, `${code}\n`);
			this.last().emit("exit", code);
		},
	};
}

function freshSession() { return `s-${randomUUID()}`; }

