describe("BgProcessManager.waitForExit — state machine", () => {
	it("abort before exit resolves with aborted:true and leaves process running", async () => {
		const h = makeManager();
		const SESSION = freshSession();
		const info = h.mgr.create(SESSION, "sleep 30", h.stateDir);
		assert.equal(info.status, "running");
		assert.equal(info.terminalReason, null);

		const controller = new AbortController();
		h.mgr.registerWait(SESSION, controller);

		const waitPromise = h.mgr.waitForExit(SESSION, info.id, 10_000, controller.signal);
		h.mgr.abortAllWaits(SESSION);
		const result = await waitPromise;
		h.mgr.unregisterWait(SESSION, controller);

		assert.ok(result, "result should not be null");
		assert.equal(result!.aborted, true);
		assert.equal(result!.timedOut, false);
		assert.equal(result!.info.status, "running");

		const still = h.mgr.list(SESSION).find(p => p.id === info.id);
		assert.ok(still);
		assert.equal(still!.status, "running");
		assert.equal(controller.signal.aborted, true);

		h.mgr.cleanup(SESSION);
	});

	it("exit resolves immediately and reflects exited status + terminalReason normal", async () => {
		const h = makeManager();
		const SESSION = freshSession();
		const info = h.mgr.create(SESSION, "noop", h.stateDir);

		const controller = new AbortController();
		const waitPromise = h.mgr.waitForExit(SESSION, info.id, 10_000, controller.signal);

		queueMicrotask(() => h.driveExit(SESSION, info.id, 0));

		const result = await waitPromise;
		assert.ok(result);
		assert.equal(result!.timedOut, false);
		assert.equal(result!.aborted, false);
		assert.equal(result!.info.status, "exited");
		assert.equal(result!.info.exitCode, 0);
		assert.equal(result!.info.terminalReason, "normal");

		h.mgr.cleanup(SESSION);
	});

	it("already-exited short-circuit returns aborted:false even with a fresh signal", async () => {
		const h = makeManager();
		const SESSION = freshSession();
		const info = h.mgr.create(SESSION, "noop", h.stateDir);

		h.driveExit(SESSION, info.id, 0); // synchronous exit before any waiter attaches

		const controller = new AbortController();
		const result = await h.mgr.waitForExit(SESSION, info.id, 1000, controller.signal);
		assert.ok(result);
		assert.equal(result!.timedOut, false);
		assert.equal(result!.aborted, false);
		assert.equal(result!.info.status, "exited");

		controller.abort();
		h.mgr.cleanup(SESSION);
	});

	it("timeout fires deterministically under fake timers", () => {
		const h = makeManager();
		const SESSION = freshSession();
		const info = h.mgr.create(SESSION, "sleep 30", h.stateDir);

		const controller = new AbortController();
		h.mgr.registerWait(SESSION, controller);

		const waitPromise = h.mgr.waitForExit(SESSION, info.id, 50, controller.signal);
		h.clock.advance(50);

		return waitPromise.then((result) => {
			assert.ok(result);
			assert.equal(result!.timedOut, true);
			assert.equal(result!.aborted, false);
			controller.abort();
			h.mgr.unregisterWait(SESSION, controller);
			h.mgr.cleanup(SESSION);
		});
	});

	it("does not leak abort listeners across many cycles", async () => {
		const h = makeManager();
		const SESSION = freshSession();
		const info = h.mgr.create(SESSION, "sleep 30", h.stateDir);

		const controller = new AbortController();
		const signal = controller.signal;
		let active = 0;
		let peak = 0;
		const origAdd = signal.addEventListener.bind(signal);
		const origRemove = signal.removeEventListener.bind(signal);
		signal.addEventListener = ((type: string, listener: any, opts?: any) => {
			if (type === "abort") { active++; peak = Math.max(peak, active); }
			return origAdd(type, listener, opts);
		}) as any;
		signal.removeEventListener = ((type: string, listener: any, opts?: any) => {
			if (type === "abort") active = Math.max(0, active - 1);
			return origRemove(type, listener, opts);
		}) as any;

		for (let i = 0; i < 200; i++) {
			const p = h.mgr.waitForExit(SESSION, info.id, 1, signal);
			await Promise.resolve();
			h.clock.advance(1);
			await p;
		}

		assert.equal(active, 0, "abort listener must be removed when wait settles via timeout");
		assert.ok(peak <= 1, `at most one abort listener should be live at a time, peak=${peak}`);
		assert.equal(h.last().listenerCount("exit"), 1, "only the manager's create() exit hint should remain");

		h.mgr.cleanup(SESSION);
	});

	it("multiple concurrent waits all abort on abortAllWaits()", async () => {
		const h = makeManager();
		const SESSION = freshSession();
		const info = h.mgr.create(SESSION, "sleep 30", h.stateDir);

		const c1 = new AbortController();
		const c2 = new AbortController();
		const c3 = new AbortController();
		h.mgr.registerWait(SESSION, c1);
		h.mgr.registerWait(SESSION, c2);
		h.mgr.registerWait(SESSION, c3);

		const p1 = h.mgr.waitForExit(SESSION, info.id, 10_000, c1.signal);
		const p2 = h.mgr.waitForExit(SESSION, info.id, 10_000, c2.signal);
		const p3 = h.mgr.waitForExit(SESSION, info.id, 10_000, c3.signal);

		h.mgr.abortAllWaits(SESSION);
		const [r1, r2, r3] = await Promise.all([p1, p2, p3]);

		for (const r of [r1, r2, r3]) {
			assert.ok(r);
			assert.equal(r!.aborted, true);
			assert.equal(r!.info.status, "running");
		}

		h.mgr.unregisterWait(SESSION, c1);
		h.mgr.unregisterWait(SESSION, c2);
		h.mgr.unregisterWait(SESSION, c3);
		h.mgr.cleanup(SESSION);
	});

	it("cleanup() aborts in-flight waits and signals running children", async () => {
		const h = makeManager({ isHostPidAlive: () => true });
		const SESSION = freshSession();
		const info = h.mgr.create(SESSION, "sleep 30", h.stateDir);

		const controller = new AbortController();
		h.mgr.registerWait(SESSION, controller);
		const waitPromise = h.mgr.waitForExit(SESSION, info.id, 10_000, controller.signal);

		h.mgr.cleanup(SESSION);

		const result = await waitPromise;
		assert.ok(result);
		assert.equal(result!.aborted, true, "cleanup must abort the pending wait");
		assert.ok(h.killCalls.length >= 1, "cleanup must signal running children via env.killHostTree");
	});

	it("waitForExit on unknown processId returns null", async () => {
		const h = makeManager();
		const result = await h.mgr.waitForExit(freshSession(), "bg-does-not-exist", 100);
		assert.equal(result, null);
	});

	it("pre-aborted signal returns immediately without arming the timer", () => {
		const h = makeManager();
		const SESSION = freshSession();
		const info = h.mgr.create(SESSION, "sleep 30", h.stateDir);

		const controller = new AbortController();
		controller.abort();

		return h.mgr.waitForExit(SESSION, info.id, 10_000, controller.signal).then((result) => {
			assert.ok(result);
			assert.equal(result!.aborted, true);
			assert.equal(result!.timedOut, false);
			// Drain past the would-be timeout window; a bounded advance avoids draining
			// the self-rescheduling status-poll interval forever (runAll would loop).
			h.clock.advance(10_000);
			h.mgr.cleanup(SESSION);
		});
	});
});

describe("BgProcessManager spawn failures", () => {
	it("rejects a missing host cwd before allocating an ID, persisting, or spawning", () => {
		const h = makeManager();
		const session = freshSession();
		const rawPathSentinel = "/private/DO-NOT-LEAK/missing-cwd";

		assert.throws(() => h.mgr.create(session, "noop", rawPathSentinel), (error: any) => {
			assert.equal(error?.publicCode, "BG_CWD_MISSING");
			assert.match(error?.message ?? "", /working directory.*available/i);
			assert.doesNotMatch(JSON.stringify(error), /DO-NOT-LEAK/);
			return true;
		});
		assert.equal(h.spawnCalls(), 0, "preflight must run before spawn");
		assert.equal(h.store.getForSession(session).length, 0, "preflight must not persist a phantom record");

		const next = h.mgr.create(session, "echo ok", h.stateDir);
		assert.equal(next.id, "bg-1", "a rejected create must not consume an ID");
		h.mgr.cleanup(session);
	});

	it("rejects a host cwd that is a file with a stable, sanitized diagnostic", () => {
		const h = makeManager();
		const session = freshSession();
		const cwdFile = path.join(h.stateDir, "not-a-directory-SECRET-SENTINEL");
		fs.writeFileSync(cwdFile, "not a directory");

		assert.throws(() => h.mgr.create(session, "noop", cwdFile), (error: any) => {
			assert.equal(error?.publicCode, "BG_CWD_NOT_DIRECTORY");
			assert.match(error?.message ?? "", /directory/i);
			assert.doesNotMatch(JSON.stringify(error), /SECRET-SENTINEL/);
			assert.deepEqual(error?.diagnostic, { operation: "stat-cwd", code: "ENOTDIR" });
			return true;
		});
		assert.equal(h.spawnCalls(), 0);
		assert.equal(h.store.getForSession(session).length, 0);
	});

	it("maps permission and unknown cwd stat failures to sanitized, stable diagnostics", () => {
		const h = makeManager();
		const session = freshSession();
		const originalStat = (fs as any).statSync;
		try {
			for (const [nativeCode, safeCode] of [["EACCES", "EACCES"], ["WEIRD_NATIVE_CODE", "UNKNOWN"]]) {
				(fs as any).statSync = (target: string) => {
					if (target === h.stateDir) throw Object.assign(new Error(`/private/CWD-STAT-SECRET ${nativeCode}`), { code: nativeCode });
					return originalStat(target);
				};
				assert.throws(() => h.mgr.create(session, "noop", h.stateDir), (error: any) => {
					assert.equal(error?.publicCode, "BG_CWD_UNAVAILABLE");
					assert.deepEqual(error?.diagnostic, { operation: "stat-cwd", code: safeCode });
					assert.doesNotMatch(JSON.stringify(error), /CWD-STAT-SECRET|WEIRD_NATIVE_CODE/);
					return true;
				});
			}
			assert.equal(h.spawnCalls(), 0);
			assert.equal(h.store.getForSession(session).length, 0);
		} finally {
			(fs as any).statSync = originalStat;
		}
	});

	it("error-only child never throws unhandled, terminalizes once, stops machinery, persists, broadcasts, and settles waits", async () => {
		const h = makeManager();
		const session = freshSession();
		const info = h.mgr.create(session, "noop", h.stateDir);
		const child = h.last();
		const nativeEmit = child.emit.bind(child);
		let suppressedUnhandledError: Error | null = null;
		child.emit = ((event: string | symbol, ...args: unknown[]) => {
			if (event === "error" && child.listenerCount("error") === 0) {
				suppressedUnhandledError = args[0] as Error;
				return false;
			}
			return nativeEmit(event, ...args);
		}) as typeof child.emit;

		const wait = h.mgr.waitForExit(session, info.id, 10_000);
		const rawCause = Object.assign(new Error("ENOENT /private/SECRET-SPAWN-PATH"), { code: "ENOENT" });
		child.emit("error", rawCause); // deliberately never emits exit
		assert.equal(suppressedUnhandledError, null, "the native error event must always have a listener");
		assert.equal(h.mgr.list(session).find(p => p.id === info.id)?.status, "exited", "an error-only child must not remain running");
		const result = await wait;

		assert.ok(result);
		assert.equal(result!.timedOut, false);
		assert.equal(result!.info.status, "exited");
		assert.equal(result!.info.exitCode, null);
		assert.equal((result!.info as any).terminalReason, "spawn-failed");
		const spawnFailure = (result!.info as any).spawnFailure;
		assert.equal(spawnFailure.kind, "spawn");
		assert.equal(spawnFailure.code, "ENOENT");
		assert.match(spawnFailure.message, /\bcould not be started\b/i, "safe diagnostic identifies the actionable start failure");
		assert.equal(h.tailerStops.length, 2, "both tailers stop exactly once");
		const runtime = (h.mgr as any).processes.get(session).get(info.id);
		assert.equal(runtime._statusTimer, null, "status watcher is cancelled");
		assert.equal(runtime._projectionTimer, null, "projection debounce is cancelled");
		assert.equal(runtime._killEscalate, null, "kill escalation is cancelled");
		h.tailerSpecs[0].onChunk("stdout", "late tailer output\\n", 18);
		assert.equal(h.mgr.getLogs(session, info.id)?.log.length, 0, "late tailer chunks are ignored after terminalization");
		assert.equal(h.sent.filter((message) => message.type === "bg_process_output").length, 0);
		const persisted = h.store.get(session, info.id)! as any;
		assert.equal(persisted.terminalReason, "spawn-failed");
		assert.deepEqual(persisted.spawnFailure, spawnFailure);
		assert.doesNotMatch(JSON.stringify({ persisted, sent: h.sent }), /SECRET-SPAWN-PATH/, "raw runtime causes never cross persistence or WS");
		const exited = h.sent.filter((message) => message.type === "bg_process_exited");
		assert.deepEqual(exited, [{ type: "bg_process_exited", processId: info.id, exitCode: null, endTime: result!.info.endTime, terminalReason: "spawn-failed", spawnFailure }]);

		h.driveExit(session, info.id, 0); // late status + exit cannot overwrite or announce again
		assert.equal(h.mgr.list(session)[0].terminalReason, "spawn-failed");
		assert.equal(h.sent.filter((message) => message.type === "bg_process_exited").length, 1);
		h.mgr.cleanup(session);
	});

	it("cancels pending Docker PID retries after a runtime error and permits a later normal create", async () => {
		let pidReads = 0;
		const h = makeManager({ dockerCli(argv) {
			if (argv.includes("cat") && argv[argv.length - 1].endsWith(".pid")) { pidReads++; return { code: 1, stdout: "" }; }
			return { code: 0, stdout: "" };
		} });
		const session = freshSession();
		const first = h.mgr.create(session, "noop", "/container/workspace", "container-id");
		const readsBeforeError = pidReads;
		h.last().emit("error", Object.assign(new Error("docker spawn failed"), { code: "EACCES" }));
		h.clock.advance(10_000);
		const runtime = (h.mgr as any).processes.get(session).get(first.id);
		assert.equal(runtime._pidResolveTimer, null, "terminalization cancels the owned Docker PID retry");
		assert.equal(pidReads, readsBeforeError, "a terminal record must not keep scheduling Docker PID reads");
		assert.equal((h.mgr.list(session).find(p => p.id === first.id) as any).terminalReason, "spawn-failed");

		const second = h.mgr.create(session, "echo ok", "/container/workspace", "container-id");
		assert.equal(second.id, "bg-2");
		h.driveExit(session, second.id, 0);
		const completed = await h.mgr.waitForExit(session, second.id, 1000);
		assert.equal(completed?.info.terminalReason, "normal", "a failed spawn must not poison later commands");
		h.mgr.cleanup(session);
	});

	it("skips host cwd stat for Docker while retaining sandbox refusal before either stat or spawn", () => {
		const h = makeManager({ dockerCli: () => ({ code: 0, stdout: "123\n" }) });
		const session = freshSession();
		let stats = 0;
		const originalStat = (fs as any).statSync;
		(fs as any).statSync = (...args: unknown[]) => { stats++; return originalStat(...args); };
		try {
			h.mgr.create(session, "noop", "/missing-only-inside-container", "container-id");
			assert.equal(stats, 0, "Docker cwd is authoritative inside the container, never preflighted on host");
			assert.throws(() => h.mgr.create(session, "noop", h.stateDir, undefined, true), /Sandboxed session/);
			assert.equal(stats, 0, "sandbox guard precedes host cwd validation");
			assert.equal(h.spawnCalls(), 1, "sandbox refusal must not spawn");
		} finally {
			(fs as any).statSync = originalStat;
			h.mgr.cleanup(session);
		}
	});

	it("Docker primary non-zero waits for status grace, then a later wrapper status wins with its exact code", async () => {
		const pidNonces = new Map<string, string>();
		const statuses = new Map<string, string>();
		let statusReads = 0;
		const h = makeManager({ dockerCli(argv) {
			const target = argv.at(-1) ?? "";
			if (target.endsWith(".pid")) return { code: 0, stdout: `4242\n${pidNonces.get(target) ?? ""}\n` };
			if (target.endsWith(".status")) {
				statusReads++;
				const status = statuses.get(target);
				return status == null ? { code: 1, stdout: "" } : { code: 0, stdout: status };
			}
			if (argv[0] === "inspect" || argv.includes("-0")) return { code: 0, stdout: argv[0] === "inspect" ? "true\n" : "" };
			return { code: 0, stdout: "" };
		} }, (paths) => pidNonces.set(paths.containerPid!, paths.nonce));
		const session = freshSession();
		try {
			const info = h.mgr.create(session, "noop", "/workspace", "container-id");
			const wait = h.mgr.waitForExit(session, info.id, 10_000);
			const runtime = (h.mgr as any).processes.get(session).get(info.id);
			h.last().emit("exit", 125); // first container-status read is unavailable
			assert.ok(statusReads >= 1, "the primary exit attempts a status read before fallback");
			assert.equal(h.mgr.list(session).find(p => p.id === info.id)?.status, "running", "a missing first status read stays live during grace");
			h.clock.advance(1_400);
			assert.equal(h.mgr.list(session).find(p => p.id === info.id)?.status, "running", "the bounded grace has not elapsed");

			statuses.set(runtime.paths.containerStatus, "37\n"); // wrapper status appears after the failed read
			h.clock.advance(200);
			const result = await wait;
			assert.equal(result?.timedOut, false);
			assert.equal(result?.info.terminalReason, "normal");
			assert.equal(result?.info.exitCode, 37, "durable wrapper code, not Docker's 125, wins");
			assert.equal((h.store.get(session, info.id) as any).exitCode, 37, "real wrapper result persists");
			assert.equal(runtime._tailers, null, "terminalization stops tailers");
			assert.equal(runtime._statusTimer, null, "terminalization stops the watcher");
			assert.equal(runtime._pidResolveTimer, null, "terminalization stops pid retries");
			assert.equal(h.tailerStops.length, 2, "both tailers stop once");
			assert.equal(h.sent.filter(m => m.type === "bg_process_exited").length, 1, "one terminal broadcast");

			assert.doesNotThrow(() => h.last().emit("error", Object.assign(new Error("late"), { code: "ENOENT" })));
			h.last().emit("exit", 125);
			assert.equal(h.mgr.list(session).find(p => p.id === info.id)?.exitCode, 37, "late events cannot overwrite the wrapper result");
			assert.equal(h.sent.filter(m => m.type === "bg_process_exited").length, 1, "late events cannot double-report");
		} finally {
			h.mgr.cleanup(session);
		}
	});

	it("Docker setup failure without any status terminalizes once only after its grace window", async () => {
		const pidNonces = new Map<string, string>();
		const h = makeManager({ dockerCli(argv) {
			const target = argv.at(-1) ?? "";
			if (target.endsWith(".pid")) return { code: 0, stdout: `4242\n${pidNonces.get(target) ?? ""}\n` };
			if (target.endsWith(".status")) return { code: 1, stdout: "" };
			if (argv[0] === "inspect" || argv.includes("-0")) return { code: 0, stdout: argv[0] === "inspect" ? "true\n" : "" };
			return { code: 0, stdout: "" };
		} }, (paths) => pidNonces.set(paths.containerPid!, paths.nonce));
		const session = freshSession();
		try {
			const info = h.mgr.create(session, "noop", "/workspace", "container-id");
			const wait = h.mgr.waitForExit(session, info.id, 10_000);
			const runtime = (h.mgr as any).processes.get(session).get(info.id);
			h.last().emit("exit", 126);
			assert.equal(h.mgr.list(session).find(p => p.id === info.id)?.status, "running", "missing status does not synthesize setup failure immediately");
			h.clock.advance(1_400);
			assert.equal(h.mgr.list(session).find(p => p.id === info.id)?.status, "running", "failure is still deferred inside grace");
			h.clock.advance(200);
			const result = await wait;
			assert.equal(result?.timedOut, false, "the deferred failure settles waiters");
			assert.equal(result?.info.terminalReason, "spawn-failed");
			assert.equal(result?.info.exitCode, null);
			assert.deepEqual((h.store.get(session, info.id) as any).spawnFailure, { kind: "spawn", code: "UNKNOWN", message: "Background process could not be started" }, "failure is persisted");
			assert.equal(runtime._tailers, null, "failure cleanup stops tailers");
			assert.equal(runtime._statusTimer, null, "failure cleanup stops status polling");
			assert.equal(runtime._pidResolveTimer, null, "failure cleanup stops pid retries");
			assert.equal(h.tailerStops.length, 2, "failure stops each tailer once");
			assert.equal(h.sent.filter(m => m.type === "bg_process_exited").length, 1, "one deferred failure broadcast");

			h.last().emit("exit", 126);
			assert.doesNotThrow(() => h.last().emit("error", Object.assign(new Error("late"), { code: "ENOENT" })));
			assert.equal(h.sent.filter(m => m.type === "bg_process_exited").length, 1, "late events cannot resurrect or double-report failure");
		} finally {
			h.mgr.cleanup(session);
		}
	});

	it("Docker kill intent remains authoritative while status fallback is pending", async () => {
		const pidNonces = new Map<string, string>();
		const h = makeManager({ dockerCli(argv) {
			const target = argv.at(-1) ?? "";
			if (target.endsWith(".pid")) return { code: 0, stdout: `4242\n${pidNonces.get(target) ?? ""}\n` };
			if (target.endsWith(".status")) return { code: 1, stdout: "" };
			if (argv[0] === "inspect" || argv.includes("-0")) return { code: 1, stdout: argv[0] === "inspect" ? "false\n" : "" };
			return { code: 0, stdout: "" };
		} }, (paths) => pidNonces.set(paths.containerPid!, paths.nonce));
		const session = freshSession();
		try {
			const info = h.mgr.create(session, "noop", "/workspace", "container-id");
			const wait = h.mgr.waitForExit(session, info.id, 10_000);
			assert.equal(h.mgr.kill(session, info.id), true);
			h.last().emit("exit", 125);
			assert.equal(h.mgr.list(session).find(p => p.id === info.id)?.status, "running", "primary nonzero cannot rewrite a requested kill");
			h.clock.advance(2_000);
			const result = await wait;
			assert.equal(result?.info.terminalReason, "killed");
			assert.equal(result?.info.exitCode, null);
		} finally {
			h.mgr.cleanup(session);
		}
	});
});

describe("spawn-failure protocol contract", () => {
	it("broadcasts the safe diagnostic in the typed terminal event", () => {
		const event: ServerMessage = {
			type: "bg_process_exited", processId: "bg-1", exitCode: null, endTime: 2,
			terminalReason: "spawn-failed",
			spawnFailure: { kind: "spawn", code: "UNKNOWN", message: "Background process failed to start." },
		};
		assert.equal(event.type, "bg_process_exited");
		assert.equal((event as any).spawnFailure.code, "UNKNOWN");
	});
});

describe("bash_bg spawn-failure text", () => {
	it("wait and list show a concise failed-to-start diagnostic instead of a null exit code", async () => {
		const prior = {
			sessionId: process.env.BOBBIT_SESSION_ID,
			token: process.env.BOBBIT_TOKEN,
			url: process.env.BOBBIT_GATEWAY_URL,
		};
		process.env.BOBBIT_SESSION_ID = "test-session";
		process.env.BOBBIT_TOKEN = "test-token";
		process.env.BOBBIT_GATEWAY_URL = "http://gateway.test";
		const failed = {
			id: "bg-1", name: "compile", command: "npm run build", pid: 0, status: "exited", exitCode: null,
			terminalReason: "spawn-failed", startTime: 1, endTime: 2,
			spawnFailure: { kind: "spawn", code: "ENOENT", message: "Background process failed to start." },
		};
		vi.stubGlobal("fetch", vi.fn(async (input: string | URL) => {
			const url = String(input);
			const body = url.includes("/wait?")
				? { info: failed, timedOut: false, aborted: false }
				: { processes: [failed] };
			return new Response(JSON.stringify(body), { status: 200, headers: { "Content-Type": "application/json" } });
		}));
		const tools: any[] = [];
		try {
			shellExtension({ registerTool: (tool: any) => tools.push(tool) } as any);
			const execute = tools.find((tool) => tool.name === "bash_bg").execute;
			const waited = await execute("call", { action: "wait", id: "bg-1", timeout: 1 });
			const listed = await execute("call", { action: "list" });
			for (const result of [waited, listed]) {
				const text = result.content[0].text;
				assert.match(text, /\b(?:could not be started|failed to start)\b/i, "response identifies the actionable start failure");
				assert.doesNotMatch(text, /code null|\[exited\]/i);
			}
		} finally {
			vi.unstubAllGlobals();
			for (const [key, value] of Object.entries(prior)) {
				if (value == null) delete process.env[key]; else process.env[key] = value;
			}
		}
	});
});

describe("BgProcessManager endTime snapshots", () => {
	it("created/running process info exposes endTime null", () => {
		const h = makeManager();
		const SESSION = freshSession();
		const info = h.mgr.create(SESSION, "sleep 30", h.stateDir);
		try {
			assert.equal((info as { endTime?: unknown }).endTime, null, "running BgProcessInfo must include endTime: null");
		} finally {
			h.mgr.cleanup(SESSION);
		}
	});

	it("list() and waitForExit() expose numeric endTime after exit", async () => {
		const h = makeManager();
		const SESSION = freshSession();
		const info = h.mgr.create(SESSION, "noop", h.stateDir);

		try {
			const waitPromise = h.mgr.waitForExit(SESSION, info.id, 10_000);
			queueMicrotask(() => h.driveExit(SESSION, info.id, 0));

			const result = await waitPromise;
			assert.ok(result);
			const listed = h.mgr.list(SESSION).find((p) => p.id === info.id);
			assert.ok(listed);

			const listEndTime = (listed as { endTime?: unknown }).endTime;
			const waitEndTime = (result!.info as { endTime?: unknown }).endTime;

			assert.equal(typeof listEndTime, "number", "exited list() snapshot must include numeric endTime");
			assert.equal(typeof waitEndTime, "number", "waitForExit() snapshot must include numeric endTime");
			assert.ok((listEndTime as number) >= info.startTime, "list() endTime must be at or after startTime");
			assert.equal(waitEndTime, listEndTime, "waitForExit() and list() should report the same final endTime");
		} finally {
			h.mgr.cleanup(SESSION);
		}
	});
});

